/* Read-only reconstruction after successful Program 174. */
WITH run_context AS (SELECT run_id, run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1) SELECT run_status, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM run_context)) AS latest_rows, (SELECT canonical_entities FROM msbf_m2.v_m2_6_canonical_hash WHERE module1_run_id=(SELECT run_id FROM run_context)) AS canonical_entities, CASE WHEN run_status IN ('M2_6_GENERATED','M2_6_VALIDATED','M2_6_ACCEPTED') THEN 'PASS' ELSE 'FAIL' END AS generation_reconstruction_status FROM run_context;
